def incassi_esistenti(apps, schema_editor):
    """Le scadenze già segnate incassate diventano un incasso del loro importo."""
    Scadenza = apps.get_model("fatturazione", "Scadenza")
    Incasso = apps.get_model("fatturazione", "Incasso")
    for s in Scadenza.objects.filter(pagata=True):
        Incasso.objects.create(scadenza=s, importo=s.importo, data=s.pagata_il or s.data)
        Scadenza.objects.filter(pk=s.pk).update(incassato=s.importo)


